const form=document.getElementById('login'),btn=document.getElementById('submit'),msg=document.getElementById('message');
let expectedRole='account_manager';const roleCaption=document.getElementById('role-caption');
document.querySelectorAll('[data-role]').forEach(choice=>choice.addEventListener('click',()=>{expectedRole=choice.dataset.role;document.querySelectorAll('[data-role]').forEach(x=>x.setAttribute('aria-pressed',String(x===choice)));if(roleCaption)roleCaption.textContent=expectedRole==='admin'?'For the workspace administrator. Your assigned role is verified after sign-in.':'For Account Manager accounts. Your assigned role is verified after sign-in.';}));
function show(text){msg.textContent=text;msg.classList.add('show')}
form.addEventListener('submit',async e=>{e.preventDefault();msg.classList.remove('show');const email=document.getElementById('email').value.trim(),password=document.getElementById('password').value;if(!email||!password){show('Enter your email and password.');return}btn.disabled=true;btn.textContent='Signing in…';try{const cr=await fetch('/api/auth/csrf',{credentials:'same-origin',cache:'no-store'});if(!cr.ok)throw new Error('Could not start a secure session. Refresh and try again.');const {csrfToken}=await cr.json();const r=await fetch('/api/auth/login',{method:'POST',credentials:'same-origin',headers:{'Content-Type':'application/json','X-CSRF-Token':csrfToken},body:JSON.stringify({email,password,expectedRole})});const data=await r.json().catch(()=>({}));if(!r.ok)throw new Error(data.error||'Sign-in failed. Check your details and try again.');const me=await fetch('/api/auth/me',{credentials:'same-origin',cache:'no-store'});const session=await me.json().catch(()=>({}));const actualRole=(session.user&&session.user.role)||(data.user&&data.user.role);if(actualRole&&actualRole!==expectedRole){await fetch('/api/auth/logout',{method:'POST',credentials:'same-origin',headers:{'X-CSRF-Token':csrfToken}}).catch(()=>{});throw new Error('This account is not an '+(expectedRole==='admin'?'Admin':'Account Manager')+' account. Choose the matching login option.');}location.replace('/index.html')}catch(err){show(err.message||'Network error. Please try again.')}finally{btn.disabled=false;btn.textContent='Sign in securely ↗'}});
